"""Programme eligibility monitoring. Traces: R27."""
from __future__ import annotations

from dataclasses import dataclass, field
from config.models import ProgrammeTier
from config.tier_manager import TierManager, _TIER_ORDER


@dataclass
class EligibilityAlert:
    """Alert generated by eligibility monitoring."""
    user_id: str
    alert_type: str  # "downgrade_risk" | "upgrade_opportunity"
    current_tier: str
    target_tier: str = ""
    message: str = ""
    corrective_actions: list[str] = field(default_factory=list)


class EligibilityMonitor:
    """Monitors user metrics against tier criteria and generates proactive alerts.

    Configurable evaluation frequency (default: monthly).
    Traces: R27.1, R27.2, R27.3, R27.4, R27.5.
    """

    def __init__(
        self,
        tier_manager: TierManager | None = None,
        evaluation_frequency: str = "monthly",
    ):
        self.tier_manager = tier_manager or TierManager()
        self.evaluation_frequency = evaluation_frequency

    def evaluate(
        self,
        user_id: str,
        current_tier: str,
        balance: float,
        salary_credit: float,
        transaction_volume: int = 0,
    ) -> list[EligibilityAlert]:
        """Evaluate user metrics against tier criteria. Returns alerts.

        Traces: R27.1, R27.2, R27.3, R27.4.
        """
        alerts: list[EligibilityAlert] = []

        # Check downgrade risk (R27.2, R27.3)
        if self.tier_manager.check_downgrade_risk(current_tier, balance, salary_credit):
            tier_def = self.tier_manager.get_tier(current_tier)
            actions = self._recommend_corrective_actions(
                current_tier, balance, salary_credit, tier_def
            )
            alerts.append(EligibilityAlert(
                user_id=user_id,
                alert_type="downgrade_risk",
                current_tier=current_tier,
                message=(
                    f"Your account metrics are below the minimum requirements for "
                    f"'{current_tier}' tier. Review your balance and salary credits "
                    f"to maintain your current tier."
                ),
                corrective_actions=actions,
            ))

        # Check upgrade opportunity (R27.4)
        upgrade_tier = self.tier_manager.evaluate_eligibility(
            current_tier, balance, salary_credit
        )
        if upgrade_tier:
            alerts.append(EligibilityAlert(
                user_id=user_id,
                alert_type="upgrade_opportunity",
                current_tier=current_tier,
                target_tier=upgrade_tier,
                message=(
                    f"You are eligible for an upgrade to '{upgrade_tier}' tier "
                    f"based on your current balance and salary credits."
                ),
            ))

        return alerts

    @staticmethod
    def _recommend_corrective_actions(
        current_tier: str,
        balance: float,
        salary_credit: float,
        tier_def: ProgrammeTier | None,
    ) -> list[str]:
        """Recommend corrective actions to maintain tier status. Traces: R27.3."""
        if tier_def is None:
            return []
        actions: list[str] = []
        if balance < tier_def.min_balance:
            shortfall = tier_def.min_balance - balance
            actions.append(
                f"Increase your balance by {shortfall:,.2f} to meet the "
                f"minimum balance requirement of {tier_def.min_balance:,.2f}."
            )
        if salary_credit < tier_def.salary_credit:
            shortfall = tier_def.salary_credit - salary_credit
            actions.append(
                f"Increase salary credits by {shortfall:,.2f} to meet the "
                f"minimum requirement of {tier_def.salary_credit:,.2f}."
            )
        return actions
